package luau_test

// Byte-exact differential tests against golden files generated by the real npm
// @roblox-ts/luau-ast 2.0.0 (testdata/generate.js).
//
// To run extra golden files, for example ones dumped from a patched upstream
// compiler with testdata/graph.js, set LUAU_EXTRA_GOLDEN to a directory of
// *.json files in the same format as testdata/golden/handwritten.json. They are
// skipped when the variable is unset.

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"strconv"
	"testing"

	"github.com/microsoft/TypeScript/tsc/rbxtsgo/luau"
)

type goldenCase struct {
	Name     string            `json:"name"`
	Mode     string            `json:"mode"`
	Graph    graphJSON         `json:"graph"`
	Expected *string           `json:"expected"`
	Error    *string           `json:"error"`
	Temps    map[string]string `json:"temps"`
}

type goldenFile struct {
	LuauAstVersion string       `json:"luauAstVersion"`
	Cases          []goldenCase `json:"cases"`
}

// runGoldenCase renders the case and returns its output, the solved temp
// names (nil for modes without a state) and the assertion message, if any.
func runGoldenCase(t testing.TB, c *goldenCase) (out string, temps map[int]string, assertion string) {
	t.Helper()
	l := loadGraph(t, &c.Graph)
	root := l.root(c.Graph.Roots["ast"])

	defer func() {
		if r := recover(); r != nil {
			ae, ok := r.(*luau.AssertionError)
			if !ok {
				panic(r)
			}
			assertion = ae.Error()
		}
	}()

	list, _ := root.(*luau.List)
	node, _ := root.(luau.Node)

	state := luau.NewRenderState()
	switch c.Mode {
	case "renderAST":
		// RenderAST has no visible state: solve separately for the temp names.
		solved := luau.NewRenderState()
		luau.SolveTempIDs(solved, list)
		temps = solved.SeenTempNodes
		out = luau.RenderAST(list)
		return
	case "renderStatements":
		luau.SolveTempIDs(state, list)
		out = luau.RenderStatements(state, list)
	case "render":
		luau.SolveTempIDs(state, node)
		out = luau.Render(state, node)
	case "renderUnsolved":
		out = luau.Render(state, node)
	case "renderStatementsUnsolved":
		out = luau.RenderStatements(state, list)
	default:
		t.Fatalf("%s: unknown mode %q", c.Name, c.Mode)
	}
	temps = state.SeenTempNodes
	return
}

func checkGoldenCase(t *testing.T, c *goldenCase) {
	t.Helper()
	got, temps, assertion := runGoldenCase(t, c)
	if c.Error != nil {
		if assertion != *c.Error {
			t.Errorf("%s: want assertion %q, got %q (output %q)", c.Name, *c.Error, assertion, got)
		}
		return
	}
	if assertion != "" {
		t.Errorf("%s: unexpected assertion: %s", c.Name, assertion)
		return
	}
	if got != *c.Expected {
		t.Errorf("%s: output differs from upstream\n--- want\n%s\n--- got\n%s", c.Name, *c.Expected, got)
		return
	}
	if len(c.Temps) != len(temps) {
		t.Errorf("%s: temp names: want %v, got %v", c.Name, c.Temps, temps)
		return
	}
	for k, want := range c.Temps {
		id, _ := strconv.Atoi(k)
		if temps[id] != want {
			t.Errorf("%s: temp id %s: want %q, got %q", c.Name, k, want, temps[id])
		}
	}
}

func runGoldenFile(t *testing.T, path string) {
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("%v (run `node generate.js` in luau/testdata)", err)
	}
	var f goldenFile
	if err := json.Unmarshal(b, &f); err != nil {
		t.Fatal(err)
	}
	if f.LuauAstVersion != "2.0.0" {
		t.Fatalf("golden file made with luau-ast %q, want 2.0.0", f.LuauAstVersion)
	}
	if len(f.Cases) == 0 {
		t.Fatal("no cases")
	}
	for i := range f.Cases {
		checkGoldenCase(t, &f.Cases[i])
	}
	t.Logf("%d cases", len(f.Cases))
}

func TestGoldenHandwritten(t *testing.T) {
	runGoldenFile(t, filepath.Join("testdata", "golden", "handwritten.json"))
}

func TestGoldenRandom(t *testing.T) {
	runGoldenFile(t, filepath.Join("testdata", "golden", "random.json"))
}

func TestGoldenExtra(t *testing.T) {
	dir := os.Getenv("LUAU_EXTRA_GOLDEN")
	if dir == "" {
		t.Skip("LUAU_EXTRA_GOLDEN not set")
	}
	files, err := filepath.Glob(filepath.Join(dir, "*.json"))
	if err != nil || len(files) == 0 {
		t.Fatalf("no golden files in %s", dir)
	}
	for _, f := range files {
		t.Run(filepath.Base(f), func(t *testing.T) { runGoldenFile(t, f) })
	}
}

// Rendering must not depend on anything outside the AST: running a case twice
// on freshly loaded graphs gives the same bytes.
func TestGoldenRepeatable(t *testing.T) {
	var f goldenFile
	readGolden(t, "handwritten.json", &f)
	for i := range f.Cases {
		c := &f.Cases[i]
		if c.Error != nil || i%7 != 0 {
			continue
		}
		a, _, _ := runGoldenCase(t, c)
		b, _, _ := runGoldenCase(t, c)
		if !reflect.DeepEqual(a, b) {
			t.Errorf("%s: not repeatable", c.Name)
		}
	}
}
